# NoorPro's own chapter summaries for Qasidat al-Burda (Imam al-Busiri, d. 696 AH), plus notes for Hizb al-Bahr and the Asma note.
# These replace the bundled third-party English (Shaykh Zakariyya Kandhlawi's translation, still in copyright).
# Each summary is NoorPro's own prose describing the chapter; the Arabic verses are classical (public domain).
BURDA = {
'burda1': dict(sub="On love of the Prophet ﷺ", en="The poet opens in the classical Arabic manner, asking himself why his tears flow mixed with blood: is it the memory of the neighbours at Dhu Salam, a breeze from Kazimah, or lightning over Idam? He admits that a lover cannot hide love, however much he denies it, and that tears, sleeplessness and a pale face bear witness against him. He asks the one who blames him to excuse him, for blame does not reach a heart in love.",
  ur="شاعر عربی قصیدے کے قدیم انداز میں آغاز کرتا ہے اور خود سے پوچھتا ہے کہ آنسو خون کے ساتھ کیوں بہہ رہے ہیں: کیا ذی سلم کے پڑوسیوں کی یاد ہے، کاظمہ کی ہوا ہے یا اِضَم پر چمکتی بجلی؟ وہ اعتراف کرتا ہے کہ عاشق اپنی محبت چھپا نہیں سکتا، آنسو، بے خوابی اور زرد چہرہ اس کے گواہ ہیں۔ وہ ملامت کرنے والے سے معذرت چاہتا ہے کہ ملامت عاشق دل تک نہیں پہنچتی۔",
  hi="शायर अरबी क़सीदे के पुराने अंदाज़ में शुरुआत करता है और ख़ुद से पूछता है कि आँसू ख़ून के साथ क्यों बह रहे हैं: क्या ज़ी सलम के पड़ोसियों की याद है, काज़िमा की हवा है या इज़म पर चमकती बिजली? वह मानता है कि आशिक़ अपनी मोहब्बत छिपा नहीं सकता; आँसू, बेख़्वाबी और पीला चेहरा उसके गवाह हैं। वह मलामत करने वाले से माफ़ी चाहता है कि मलामत आशिक़ दिल तक नहीं पहुँचती।"),
'burda2': dict(sub="On restraining the ego and desires", en="The poet turns to his own nafs, the soul that commands evil: it ignored the warning of grey hair and old age and prepared no good deeds as hospitality for that guest. He compares the ego to a nursing child that, if not weaned, keeps craving; desire must be turned away before it takes control. He warns against both hunger and fullness that lead to harm, and against obeying the ego and Shaytan, and he regrets advising others with what he has not himself practised.",
  ur="شاعر اپنے نفسِ امّارہ کی طرف متوجہ ہوتا ہے جس نے سفید بالوں اور بڑھاپے کی تنبیہ کو نظر انداز کیا اور اس مہمان کی ضیافت کے لیے کوئی نیک عمل تیار نہ کیا۔ وہ نفس کو دودھ پیتے بچے سے تشبیہ دیتا ہے جو دودھ نہ چھڑایا جائے تو چاہت میں بڑھتا رہتا ہے؛ خواہش کو قابو پانے سے پہلے پھیر دینا چاہیے۔ وہ نفس اور شیطان کی اطاعت سے خبردار کرتا ہے اور افسوس کرتا ہے کہ دوسروں کو وہ نصیحت کی جس پر خود عمل نہ کیا۔",
  hi="शायर अपने नफ़्स-ए-अम्मारा की तरफ़ मुड़ता है जिसने सफ़ेद बालों और बुढ़ापे की चेतावनी को अनदेखा किया और उस मेहमान की ख़ातिर के लिए कोई नेक अमल तैयार न किया। वह नफ़्स को दूध पीते बच्चे जैसा बताता है जिसका दूध न छुड़ाया जाए तो चाहत बढ़ती जाती है; ख़्वाहिश को क़ाबू पाने से पहले मोड़ देना चाहिए। वह नफ़्स और शैतान की बात मानने से ख़बरदार करता है और अफ़सोस करता है कि दूसरों को वह नसीहत की जिस पर ख़ुद अमल न किया।"),
'burda3': dict(sub="In praise of the Prophet ﷺ", en="The heart of the poem: the Prophet ﷺ stood in prayer through the night until his feet swelled, tied a stone to his stomach in hunger and turned away mountains of gold. He is the master of both worlds, of jinn and mankind, of Arabs and non-Arabs; the beloved whose intercession is hoped for. All prophets drew from his ocean and rain; his beauty and excellence have no partner. Praise him as you wish, the poet says, only do not say what the Christians said of their prophet.",
  ur="قصیدے کا مرکزی حصہ: نبی ﷺ رات بھر نماز میں کھڑے رہے یہاں تک کہ قدم مبارک سوج گئے، بھوک میں پیٹ پر پتھر باندھا اور سونے کے پہاڑوں سے منہ موڑ لیا۔ آپ دونوں جہانوں، جن و انس اور عرب و عجم کے سردار ہیں؛ وہ محبوب جن کی شفاعت کی امید ہے۔ تمام انبیاء نے آپ کے سمندر اور بارش سے حصہ لیا؛ آپ کے حسن و کمال میں کوئی شریک نہیں۔ شاعر کہتا ہے: جو چاہو تعریف کرو، بس وہ نہ کہو جو نصاریٰ نے اپنے نبی کے بارے میں کہا۔",
  hi="क़सीदे का बीच का हिस्सा: नबी ﷺ रात भर नमाज़ में खड़े रहे यहाँ तक कि मुबारक क़दम सूज गए, भूख में पेट पर पत्थर बाँधा और सोने के पहाड़ों से मुँह मोड़ लिया। आप दोनों जहानों, जिन्न-ओ-इंस और अरब-ओ-अजम के सरदार हैं; वह महबूब जिनकी शफ़ाअत की उम्मीद है। सारे नबियों ने आपके समंदर और बारिश से हिस्सा लिया; आपके हुस्न-ओ-कमाल में कोई शरीक नहीं। शायर कहता है: जो चाहो तारीफ़ करो, बस वह न कहो जो ईसाइयों ने अपने नबी के बारे में कहा।"),
'burda4': dict(sub="On the birth of the Prophet ﷺ", en="His birth revealed the purity of his origin. On that night the Persians sensed that misfortune was coming: the palace of Kisra cracked, the fire of the Magians went out after a thousand years, and the lake of Sawa dried up. The jinn proclaimed and lights rose; the soothsayers' knowledge was cut off as the heavens were guarded. The world bore witness that a Messenger had come.",
  ur="آپ ﷺ کی ولادت نے آپ کے نسب کی پاکیزگی ظاہر کی۔ اس رات اہلِ فارس نے آنے والی مصیبت کو محسوس کیا: کسریٰ کا محل پھٹ گیا، مجوسیوں کی ہزار سالہ آگ بجھ گئی اور ساوہ کی جھیل خشک ہو گئی۔ جنات نے اعلان کیا اور انوار بلند ہوئے؛ آسمان کی حفاظت سے کاہنوں کا علم منقطع ہو گیا۔ دنیا نے گواہی دی کہ رسول آ گئے۔",
  hi="आप ﷺ की पैदाइश ने आपके नसब की पाकीज़गी ज़ाहिर की। उस रात फ़ारस वालों ने आने वाली मुसीबत को महसूस किया: किसरा का महल फट गया, मजूसियों की हज़ार साल की आग बुझ गई और सावा की झील सूख गई। जिन्नात ने एलान किया और रौशनियाँ उठीं; आसमान की हिफ़ाज़त से काहिनों का इल्म कट गया। दुनिया ने गवाही दी कि रसूल आ गए।"),
'burda5': dict(sub="On the blessing of his call", en="Trees came at his call, walking to him as if prostrating; the cloud shaded him wherever he went. The moon was split for him, and the cave of Thawr sheltered him and his companion while the spider and the dove guarded its mouth. His touch healed the sick, his supplication brought rain to a barren year, and revelation came to him in sleep and waking, for his eyes slept but his heart did not.",
  ur="درخت آپ ﷺ کے بلانے پر گویا سجدہ کرتے ہوئے چل کر آئے؛ بادل جہاں آپ جاتے سایہ کرتا۔ آپ کے لیے چاند دو ٹکڑے ہوا، اور غارِ ثور نے آپ اور آپ کے رفیق کو پناہ دی جبکہ مکڑی اور کبوتر نے اس کا دہانہ محفوظ رکھا۔ آپ کے چھونے سے بیمار شفا پاتے، آپ کی دعا سے قحط کے سال میں بارش ہوئی، اور نیند و بیداری میں وحی آتی، کیونکہ آپ کی آنکھیں سوتیں مگر دل نہ سوتا۔",
  hi="पेड़ आप ﷺ के बुलाने पर मानो सजदा करते हुए चलकर आए; बादल जहाँ आप जाते साया करता। आपके लिए चाँद दो टुकड़े हुआ, और ग़ार-ए-सौर ने आपको और आपके साथी को पनाह दी जबकि मकड़ी और कबूतर ने उसका मुँह महफ़ूज़ रखा। आपके छूने से बीमार शिफ़ा पाते, आपकी दुआ से क़हत के साल में बारिश हुई, और नींद और जागने में वही आती, क्योंकि आपकी आँखें सोतीं मगर दिल न सोता।"),
'burda6': dict(sub="On the glory of the Quran", en="Let me describe his signs, says the poet, which appeared like a fire of hospitality on a hilltop at night. The greatest is the Quran: eternal speech of the Eternal, not bound by time, telling of the Resurrection and of ʿAd and Iram. Its verses are clear and need no other proof; they have silenced every opponent. Like the Pool of Kawthar it whitens the faces of those who drink from it, and like the Path and the Balance it establishes justice.",
  ur="شاعر کہتا ہے: مجھے آپ ﷺ کے معجزات بیان کرنے دو جو رات کو پہاڑی پر مہمان نوازی کی آگ کی طرح ظاہر ہوئے۔ سب سے بڑا معجزہ قرآن ہے: قدیم ذات کا قدیم کلام، زمانے کا پابند نہیں، جو قیامت اور عاد و ارم کی خبر دیتا ہے۔ اس کی آیات واضح ہیں اور کسی اور دلیل کی محتاج نہیں؛ انہوں نے ہر مخالف کو خاموش کر دیا۔ حوضِ کوثر کی طرح یہ پینے والوں کے چہرے روشن کرتا ہے، اور پل صراط اور میزان کی طرح عدل قائم کرتا ہے۔",
  hi="शायर कहता है: मुझे आप ﷺ के मोजिज़े बयान करने दो जो रात को पहाड़ी पर मेहमाननवाज़ी की आग की तरह ज़ाहिर हुए। सबसे बड़ा मोजिज़ा क़ुरआन है: क़दीम ज़ात का क़दीम कलाम, ज़माने का पाबंद नहीं, जो क़यामत और आद-ओ-इरम की ख़बर देता है। इसकी आयतें साफ़ हैं और किसी और दलील की मोहताज नहीं; इन्होंने हर मुख़ालिफ़ को चुप कर दिया। हौज़-ए-कौसर की तरह यह पीने वालों के चेहरे रौशन करता है, और पुल-सिरात और मीज़ान की तरह इंसाफ़ क़ायम करता है।"),
'burda7': dict(sub="On the Night Journey and Ascension", en="O best of those whose courtyard seekers hasten to! The Prophet ﷺ travelled by night from one Sanctuary to the other as the full moon travels through darkness, and rose until he reached a station no one had reached, 'two bows' length' or nearer. All the prophets and messengers gave him precedence and he led them in prayer. Through him, the poet tells the Muslims, we became the best of nations, since the best of messengers was called to the obedience of Allah.",
  ur="اے ان میں سب سے بہتر جن کی بارگاہ کی طرف حاجت مند دوڑتے ہیں! نبی ﷺ رات کو ایک حرم سے دوسرے حرم تک ایسے گئے جیسے چودھویں کا چاند اندھیرے میں چلتا ہے، اور بلند ہوتے گئے یہاں تک کہ اس مقام تک پہنچے جہاں کوئی نہ پہنچا، قابَ قوسین یا اس سے بھی قریب۔ تمام انبیاء و رسل نے آپ کو مقدم کیا اور آپ نے ان کی امامت کی۔ شاعر مسلمانوں سے کہتا ہے: آپ کے ذریعے ہم بہترین امت بنے۔",
  hi="ऐ उनमें सबसे बेहतर जिनकी बारगाह की तरफ़ ज़रूरतमंद दौड़ते हैं! नबी ﷺ रात को एक हरम से दूसरे हरम तक ऐसे गए जैसे पूर्णिमा का चाँद अँधेरे में चलता है, और ऊपर उठते गए यहाँ तक कि उस मक़ाम तक पहुँचे जहाँ कोई न पहुँचा, क़ाबा क़ौसैन या उससे भी क़रीब। सारे नबियों और रसूलों ने आपको आगे किया और आपने उनकी इमामत की। शायर मुसलमानों से कहता है: आपके ज़रिए हम बेहतरीन उम्मत बने।"),
'burda8': dict(sub="On the Prophet's struggle (jihad)", en="News of his mission struck terror into the hearts of his enemies, like a sound that startles a heedless flock. He met them in battle after battle until their spears were broken and they were left like meat on the butcher's block. His companions were like mountains in steadfastness, the religion became a guest that would not leave, and Badr, Uhud and Hunayn bore witness. Whoever is aided by the Messenger of Allah, even lions in their dens fall silent before him.",
  ur="آپ ﷺ کی بعثت کی خبر نے دشمنوں کے دلوں میں ایسی ہیبت ڈالی جیسے کوئی آواز غافل ریوڑ کو چونکا دے۔ آپ نے معرکہ در معرکہ ان کا سامنا کیا یہاں تک کہ ان کے نیزے ٹوٹ گئے۔ آپ کے صحابہ ثابت قدمی میں پہاڑوں جیسے تھے، دین ایسا مہمان بنا جو رخصت نہ ہو، اور بدر، احد اور حنین گواہ بنے۔ جس کی مدد رسول اللہ ﷺ کریں، اس کے سامنے کچھار کے شیر بھی خاموش ہو جاتے ہیں۔",
  hi="आप ﷺ की बेअसत की ख़बर ने दुश्मनों के दिलों में ऐसा डर डाला जैसे कोई आवाज़ ग़ाफ़िल रेवड़ को चौंका दे। आपने जंग पर जंग उनका सामना किया यहाँ तक कि उनके भाले टूट गए। आपके सहाबा साबित-क़दमी में पहाड़ों जैसे थे, दीन ऐसा मेहमान बना जो रुख़सत न हो, और बद्र, उहुद और हुनैन गवाह बने। जिसकी मदद रसूलुल्लाह ﷺ करें, उसके सामने माँद के शेर भी ख़ामोश हो जाते हैं।"),
'burda9': dict(sub="On seeking forgiveness and intercession", en="The poet says he has served the Prophet ﷺ with praise, hoping it will pardon the sins of a life spent in poetry and in service of worldly patrons. His trade in this world brought loss, but his praise of the Prophet is a bond he holds; for he bears the name Muhammad, and the Prophet is the most faithful in keeping a bond. If the Prophet does not take his hand on the Day of Return, he has slipped indeed — and he trusts that the one who hopes in him will not be turned away.",
  ur="شاعر کہتا ہے کہ اس نے نبی ﷺ کی مدح سے خدمت کی، اس امید پر کہ شاعری اور دنیاوی سرپرستوں کی خدمت میں گزری عمر کے گناہ معاف ہوں۔ دنیا کی تجارت میں اسے خسارہ ہوا، مگر نبی کی مدح ایک عہد ہے جسے وہ تھامے ہوئے ہے؛ اس کا نام محمد ہے اور نبی ﷺ عہد کو سب سے زیادہ پورا کرنے والے ہیں۔ اگر قیامت کے دن آپ اس کا ہاتھ نہ تھامیں تو وہ پھسل گیا — اور اسے یقین ہے کہ آپ سے امید رکھنے والا محروم نہیں لوٹایا جاتا۔",
  hi="शायर कहता है कि उसने नबी ﷺ की तारीफ़ से ख़िदमत की, इस उम्मीद पर कि शायरी और दुनियावी सरपरस्तों की ख़िदमत में गुज़री उम्र के गुनाह माफ़ हों। दुनिया की तिजारत में उसे घाटा हुआ, मगर नबी की तारीफ़ एक अहद है जिसे वह थामे हुए है; उसका नाम मुहम्मद है और नबी ﷺ अहद को सबसे ज़्यादा पूरा करने वाले हैं। अगर क़यामत के दिन आप उसका हाथ न थामें तो वह फिसल गया — और उसे यक़ीन है कि आपसे उम्मीद रखने वाला ख़ाली नहीं लौटाया जाता।"),
'burda10': dict(sub="Closing supplication", en="O most generous of creation, I have no one to turn to but you when the universal calamity comes. Your rank will not be lessened by helping me, for Allah's Name is the Generous. Among your gifts are this world and the next, and among your knowledge is that of the Tablet and the Pen. The poet tells his soul not to despair over great sins, for the mercy of Allah is vast. He ends asking his Lord not to let his hope be disappointed, and asks for blessings without end upon the Prophet ﷺ, his family and companions.",
  ur="اے مخلوق میں سب سے کریم! عام مصیبت کے وقت آپ کے سوا میرا کوئی سہارا نہیں۔ میری مدد سے آپ کی شان کم نہ ہوگی، کیونکہ اللہ کا نام کریم ہے۔ دنیا و آخرت آپ کی عطا میں سے ہیں، اور لوح و قلم کا علم آپ کے علم کا حصہ ہے۔ شاعر اپنے نفس سے کہتا ہے کہ بڑے گناہوں پر مایوس نہ ہو، اللہ کی رحمت وسیع ہے۔ آخر میں وہ اپنے رب سے دعا کرتا ہے کہ اس کی امید نامراد نہ ہو، اور نبی ﷺ، آپ کی آل اور اصحاب پر بے انتہا درود کی دعا کرتا ہے۔",
  hi="ऐ मख़लूक़ में सबसे करीम! आम मुसीबत के वक़्त आपके सिवा मेरा कोई सहारा नहीं। मेरी मदद से आपकी शान कम न होगी, क्योंकि अल्लाह का नाम करीम है। दुनिया और आख़िरत आपकी अता में से हैं, और लौह-ओ-क़लम का इल्म आपके इल्म का हिस्सा है। शायर अपने नफ़्स से कहता है कि बड़े गुनाहों पर मायूस न हो, अल्लाह की रहमत बहुत बड़ी है। आख़िर में वह अपने रब से दुआ करता है कि उसकी उम्मीद नामुराद न हो, और नबी ﷺ, आपकी आल और साथियों पर बेइंतहा दुरूद की दुआ करता है।"),
}
HIZB = dict(
 en="A litany of the Shadhili Tariqa composed by Imam Abu al-Hasan ash-Shadhili. It is made largely of Quranic verses (e.g. 33:11-12, 36:1-9, 36:66-67, 20:111, 55:19-20, 40:1-3, 85:20-22, 12:64, 7:196, 9:129) woven with supplications for steadfastness, help, forgiveness, provision, safe travel and protection from enemies, and closes with the masnoon protective formulas (Bismillahilladhi la yadurru…, A'udhu bi kalimatillah…, la hawla wa la quwwata…) and salawat. NoorPro gives this summary instead of a full translation; read it with a teacher of the tariqa.",
 ur="امام ابوالحسن شاذلی کا مرتب کردہ سلسلہ شاذلیہ کا وظیفہ۔ اس کا بڑا حصہ آیاتِ قرآنی پر مشتمل ہے، جن کے ساتھ ثابت قدمی، مدد، مغفرت، رزق، سلامتیِ سفر اور دشمنوں سے حفاظت کی دعائیں ملی ہوئی ہیں، اور آخر میں مسنون حفاظتی کلمات (بسم اللہ الذی لا یضر…، اعوذ بکلمات اللہ…، لا حول ولا قوۃ…) اور درود ہے۔ نور پرو مکمل ترجمے کے بجائے یہ خلاصہ دیتا ہے؛ اسے سلسلے کے کسی استاد کی رہنمائی میں پڑھیں۔",
 hi="इमाम अबुल हसन शाज़ली का मुरत्तब किया हुआ सिलसिला-ए-शाज़िलिया का वज़ीफ़ा। इसका बड़ा हिस्सा क़ुरआनी आयतों पर है, जिनके साथ साबित-क़दमी, मदद, मग़फ़िरत, रिज़्क़, सफ़र की सलामती और दुश्मनों से हिफ़ाज़त की दुआएँ मिली हैं, और आख़िर में मसनून हिफ़ाज़ती कलिमात (बिस्मिल्लाहिल्लज़ी ला यज़ुर्रु…, अऊज़ु बिकलिमातिल्लाह…, ला हौला वला क़ुव्वता…) और दुरूद है। नूर प्रो पूरे तर्जुमे की जगह यह ख़ुलासा देता है; इसे सिलसिले के किसी उस्ताद की रहनुमाई में पढ़ें।")
ASMA_NOTE = dict(
 ur="اللہ کے ننانوے نام معانی کے ساتھ ایپ کے \"99 Names of Allah\" حصے میں موجود ہیں۔ انفرادی ناموں کے مخصوص اعداد (وظائف) شامل نہیں کیے گئے کیونکہ ان کا کوئی قابلِ تصدیق ماخذ نہیں ملا۔",
 hi="अल्लाह के निन्यानवे नाम मायनों के साथ ऐप के \"99 Names of Allah\" हिस्से में मौजूद हैं। अलग-अलग नामों की ख़ास गिनतियाँ (वज़ाइफ़) शामिल नहीं की गईं क्योंकि उनका कोई तस्दीक़-शुदा माख़ज़ नहीं मिला।")
